// Bundles the multi-file Worker + public/ pages into a single self-contained
// dist/worker.js (pages embedded in globalThis.__PAGES__), so it can deploy
// with no static-assets folder — ideal for a tiny GitHub repo.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const DIST = path.join(ROOT, 'dist');
fs.mkdirSync(DIST, { recursive: true });

const CT = { '.html': 'text/html; charset=utf-8', '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8', '.svg': 'image/svg+xml', '.json': 'application/json',
  '.ico': 'image/x-icon', '.png': 'image/png' };

// 1) collect public/ files into a PAGES map
function walk(dir, base = '') {
  const out = {};
  for (const name of fs.readdirSync(dir)) {
    const full = path.join(dir, name);
    const rel = base + '/' + name;
    if (fs.statSync(full).isDirectory()) Object.assign(out, walk(full, rel));
    else out[rel] = { ct: CT[path.extname(name).toLowerCase()] || 'application/octet-stream', body: fs.readFileSync(full, 'utf8') };
  }
  return out;
}
const pages = walk(path.join(ROOT, 'public'));
const pagesLiteral = 'globalThis.__PAGES__ = {\n' +
  Object.entries(pages).map(([k, v]) => `  ${JSON.stringify(k)}: { ct: ${JSON.stringify(v.ct)}, body: ${JSON.stringify(v.body)} }`).join(',\n') +
  '\n};\n';

// 2) inline the source modules (strip import lines + export keywords)
function strip(src) {
  return src
    .replace(/^\s*import\s+[^;]+?from\s+['"][^'"]+['"];?\s*$/gm, '')
    .replace(/^\s*export\s+default\s*\{/m, 'const __WORKER__ = {')
    .replace(/^\s*export\s+(async\s+function|function|const|let|var|class)\b/gm, '$1');
}
const parts = ['src/lib/util.js', 'src/lib/db.js', 'src/lib/auth.js', 'src/worker.js']
  .map((f) => `// ===== ${f} =====\n` + strip(fs.readFileSync(path.join(ROOT, f), 'utf8')));

const banner = `// Dids File Storage — single-file Worker bundle (generated by tools/build-bundle.mjs).
// Serves all pages + the API from one file. Do not edit by hand; edit src/ and rebuild.\n`;

const bundle = banner + pagesLiteral + '\n' + parts.join('\n\n') + '\n\nexport default __WORKER__;\n';
fs.writeFileSync(path.join(DIST, 'worker.js'), bundle);
console.log('wrote dist/worker.js', (bundle.length / 1024).toFixed(1) + ' KB,', Object.keys(pages).length, 'pages embedded');
